local KTool = CS.Engine.Lib.KTool
local CellPrefabName = "GoodNode"
local GoodsNodeMBPath = "Game.Behaviours.GoodNodeMB"
local UIEventProxy = CS.Engine.UI.UIEventProxy
local UIModule = CS.Engine.UI.UIModule
local ImageAlterable = CS.Engine.UI.ImageAlterable
------------ import ------------

---GoodsNodeScale 道具节点缩放
local GoodsNodeScale = 0.8
local ReverseScale_ = typeof(CS.Game.Native.Common.ReverseScale)

---@class EnergyBoxDialog
---@field Quit                            UnityEngine.RectTransform
---@field RewardView                        SuperScrollView.LoopGridView
---@field CurEnergy                        UnityEngine.UI.Text
---@field EnergyBoxSlider                UnityEngine.UI.Slider
---@field BoxName                        UnityEngine.UI.Text
---@field CommonButton_Main                UnityEngine.UI.Button
---@field EBoxNotOpen                    UnityEngine.RectTransform
local EnergyBoxDialog = Class('EnergyBoxDialog')

local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local settingMgr = SettingMgr:GetInstance()
local gameUtils = CS.GameUtils

function EnergyBoxDialog:__init()
    self._initialized = false
    self.energyPointTrans = nil
end

function EnergyBoxDialog:__delete()
    self.energyPointTrans = nil
end

function EnergyBoxDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

    end))
    return coWait
end

function EnergyBoxDialog:Awake()
    self.energyPointTrans = self.CurEnergy.transform.parent:Find("EnergyPoint")
    local argument = self.controller.Argument.parameters
    self.curIndex = argument.curDailyType

    SetButtonAction(self.CommonButton_Main, function()
        local energyPoint = checkInt(self.curQuestInfo.energyPoint) - checkInt(self.questInfo.consumeEnergy)
        if energyPoint >= 0 then
            local operation1 = GameUtils.Request(Interfaces.DailyOpenBox, { type = self.curIndex }, function(request, response)
                if checkInt(response.errCode) == 0 then
                    local rewards = response.data.rewards
                    if isTable(rewards) then
                        if #rewards > 0 then
                            GoodsUtils.DrawRewards(rewards)
                            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
                        else
                            GameUtils.Toast(localize("沒有可领取的物品"))
                        end
                    end
                    ---@type DailyQuestComponent
                    local dailyQuestData = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                    dailyQuestData:UpdateBoxId(self.curIndex, response.data.newBoxId)
                    dailyQuestData:UpdateDailyPoint(self.curIndex, energyPoint)
                    self.curQuestInfo = dailyQuestData:GetDailyQuestDojoByType(self.curIndex)
                    local setting = settingMgr:GetSetting(AutoIds.IdSetting311, "EnergyBoxVo")
                    self.questInfo = setting:Get(self.curQuestInfo.energyBoxId)
                    self:FreshGridView()
                    Events.Broadcast(Constants.EventNames.EnergyBoxPointChange, { curType = self.curIndex })
                    self:RefreshCurBoxState()
                end
            end)
        else
            GameUtils.Toast(localize("能源点不足"))
        end
    end)
    self:RefreshCurBoxState()
    self:SetScrollView()

    UIEventProxy.Create(self.Quit.gameObject).onPointerClick = Bind(self, self.QuitEnergyBox)
end

function EnergyBoxDialog:RefreshCurBoxState()
    local dailyQuestData = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
    self.curQuestInfo = dailyQuestData:GetDailyQuestDojoByType(self.curIndex)
    local setting = settingMgr:GetSetting(AutoIds.IdSetting311, "EnergyBoxVo")
    self.questInfo = setting:Get(self.curQuestInfo.energyBoxId)  -- 宝箱信息

    local dailyTypeVo = QuestConfMgr:GetInstance():GetDailyQuestTypeVoByType(self.curIndex)
    --self.BoxEnergy.text = tostring(self.questInfo.consumeEnergy)
    if checkInt(self.curQuestInfo.energyPoint) >= checkInt(self.questInfo.consumeEnergy) then
        self.EnergyBoxSlider.value = 1
        self.CurEnergy.text = string.format('%s/%s', string.format_color_tag(tostring(self.curQuestInfo.energyPoint),'#000000'), string.format_color_tag(tostring(self.questInfo.consumeEnergy), '#000000'))
        self.CommonButton_Main:ResetFontStyle("B7")
        CfUtils.FillText(self.Text, localize("领取"))
    else
        self.CurEnergy.text = string.format('%s/%s', string.format_color_tag(tostring(self.curQuestInfo.energyPoint), "#EF4343"), string.format_color_tag(tostring(self.questInfo.consumeEnergy), "#000000"))
        self.EnergyBoxSlider.value = checkInt(self.curQuestInfo.energyPoint) / checkInt(self.questInfo.consumeEnergy)
        ---能量点不足说要修改按钮
        self.CommonButton_Main:ResetFontStyle("B9")
        KTool.SetActive(self.Text, false)
    end
    self.BoxName.text = self.questInfo.name
    
    CfUtils.FillImage(self.EBoxNotOpen, self.questInfo.icon)
    self.energyPointTrans.gameObject:GetComponent((typeof(ImageAlterable))):LoadSprite(dailyTypeVo.energyPoint)
end

function EnergyBoxDialog:QuitEnergyBox()
    CS.Engine.UI.UIModule.CloseDialog(self.controller)
end

function EnergyBoxDialog:SetScrollView()
    if not KTool.IsNull(self.RewardView) and not self._initialized then
        self._initialized = true
        self.RewardView:InitGridView(0, Bind(self, self.OnGetItemByIndex))
    end
    self:FreshGridView()
end

---@param listView SuperScrollView.LoopListView2 列表对象
---@param index integer @ c#中的index
function EnergyBoxDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return
    end
    local pos = index + 1
    local cell = listView:NewListViewItem(CellPrefabName)
    if not KTool.IsNull(cell) then
        -- 缩放
        local reverseScale = KTool.GetComponent(cell.gameObject, ReverseScale_)
        reverseScale.scale = GoodsNodeScale
        reverseScale:ResetScale()
        -- cell绑定的脚本
        local cellViewMB = GetLuaBehaviour(cell.gameObject, GoodsNodeMBPath)
        if not KTool.IsNull(cellViewMB) then
            if not cell.IsInitHandlerCalled then
                cell.IsInitHandlerCalled = true
                -- 设置道具icon的点击回调
                cellViewMB:Init()
            end
            cellViewMB.Env:Reload(
                    {
                        goodsId = self.questInfo.boxRewards[pos].goodsId,
                        isShowNo = true,
                        text = self.questInfo.boxRewards[pos].goodsNum,
                    }
            )
            cellViewMB.Env:SetClickCallback(function()
                local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.questInfo.boxRewards[pos].goodsId)
                if not isNull(vo) then
                    GameUtils.ShowCommonTipsBoard(cell, vo.name, vo.desc, vo.quality, vo.id)
                end
            end)
        end
    end
    return cell
end

function EnergyBoxDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.curIndex = nil
        self.controller = nil
    end))
    return coWait
end

--更新獎勵列表
function EnergyBoxDialog:FreshGridView()
    GameUtils.ReloadData(self.RewardView, #self.questInfo.boxRewards)
end

return EnergyBoxDialog

